import json, re, sys, os

d = json.load(open('outputs/pr_review.json'))
right = {}
cur = None
newno = None
for ln in open('input/pr-1496/pr_diff.txt'):
    ln = ln.rstrip('\n')
    m = re.match(r'^diff --git a/(\S+) b/(\S+)$', ln)
    if m:
        cur = m.group(2); right.setdefault(cur, set()); newno = None; continue
    m = re.match(r'^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@', ln)
    if m:
        newno = int(m.group(1)); continue
    if cur is None or newno is None: continue
    if ln.startswith('+++') or ln.startswith('---') or ln.startswith('index ') or ln.startswith('new file') or ln.startswith('similarity'):
        continue
    if ln.startswith('\\'):   # "\ No newline at end of file"
        continue
    if ln.startswith('+'):
        right[cur].add(newno); newno += 1
    elif ln.startswith('-'):
        pass                   # old-side only
    else:                      # context ' ' (or empty context line)
        right[cur].add(newno); newno += 1

ok = True
for c in d["inlineComments"]:
    for field in ("line", "startLine"):
        if c[field] not in right.get(c["path"], set()):
            ok = False
            print(f"ANCHOR MISS: {c['path']}:{c[field]}")
print("anchors:", "ALL IN DIFF (right side)" if ok else "MISSES FOUND")
for c in d["inlineComments"]:
    in_add = c["line"] in right.get(c["path"], set())
    print(f"  {c['severity']:<10} {c['path']}:{c['line']} -> {'ok' if in_add else 'MISS'}")
sys.exit(0 if ok else 1)
